document.addEventListener('DOMContentLoaded', function(){
    const contactSelect = document.querySelector('.js-contact-select');
    const quoteSelect = document.querySelector('.js-contact-quote-select');

    if(contactSelect) { NiceSelect.bind(contactSelect, { placeholder: 'Select'}); }
    if(quoteSelect) { NiceSelect.bind(quoteSelect, { placeholder: 'Project Type'}); }

    const formContact = document.querySelector('.block-contact .wpcf7-form');
    const formContactInner = document.querySelector('.block-contact .block-contact__form');

    if(formContact) {
        formContact.addEventListener('wpcf7mailsent', function() {
            window.locoScroll.update();
            window.locoScroll.scrollTo(formContactInner);
        }, false);
    }
});;
