// Loader
let showLoader;
if (sessionStorage.getItem('homeLoaded') == null) {
    showLoader = true;
    sessionStorage.setItem('homeLoaded', 'true');
} else {
    showLoader = false;
}

// Hero away state
function heroAway() {
    const blockWorks = document.getElementById('js-block-works');
    fullpage_api.setAllowScrolling(false);
    document.body.dataset.hero = 'away';
    setTimeout(() => {
        locoScroll.start();
        locoScroll.scrollTo(blockWorks);
    }, 200);
}

document.addEventListener('DOMContentLoaded', function() {
    // Locomotive scroll stop
    window.locoScroll.stop();

    // Fullpage sroll
    const fullPageScroll = new fullpage('#js-fullpage', {
        licenseKey: 'WPL08-Q88L9-22K18-0UPJ9-NAMLO',
        credits: {
            enabled: false
        },
        onLeave: function(origin, destination, direction, trigger){
            if (direction === 'down') { heroAway(); }
        },
    });

    // Loader
    if(showLoader) {
        document.body.dataset.loader = 'show';
        fullpage_api.setAllowScrolling(false);
        setTimeout(() => { fullpage_api.setAllowScrolling(true); }, 7000);
    } else {
        document.body.dataset.loader = 'hide';
    }

    // Scroll down hero hand
    const scrollDownHand = document.querySelector('.js-banner-hero-icon');
    scrollDownHand.addEventListener('click', () => { heroAway(); });
});;
